ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS ranking_opt_in boolean NOT NULL DEFAULT false;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS public_alias text;
CREATE TABLE public.material_goals(user_id uuid NOT NULL, material_id text NOT NULL REFERENCES public.materials(id), kg numeric NOT NULL DEFAULT 1 CHECK (kg > 0), PRIMARY KEY(user_id,material_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.material_goals TO authenticated; GRANT ALL ON public.material_goals TO service_role;
ALTER TABLE public.material_goals ENABLE ROW LEVEL SECURITY;
CREATE POLICY goals_owner ON public.material_goals FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.point_suggestions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,point_id uuid NOT NULL REFERENCES public.collection_points(id),horario text,materiales text[],lat double precision,lng double precision,nota text NOT NULL DEFAULT '',estado text NOT NULL DEFAULT 'pendiente' CHECK(estado IN ('pendiente','aprobada','rechazada')),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.point_suggestions TO authenticated; GRANT ALL ON public.point_suggestions TO service_role;
ALTER TABLE public.point_suggestions ENABLE ROW LEVEL SECURITY;
CREATE POLICY suggestions_read ON public.point_suggestions FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'super_admin') OR EXISTS(SELECT 1 FROM public.collection_points p WHERE p.id=point_id AND p.admin_id=auth.uid()));
CREATE POLICY suggestions_insert ON public.point_suggestions FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND estado='pendiente');
ALTER TABLE public.recycling_logs ADD COLUMN IF NOT EXISTS client_id uuid;
CREATE UNIQUE INDEX recycling_client_id ON public.recycling_logs(user_id,client_id) WHERE client_id IS NOT NULL;
CREATE OR REPLACE FUNCTION public.community_ranking(_sector text DEFAULT NULL) RETURNS TABLE(alias text,sector text,kg numeric) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT COALESCE(NULLIF(p.public_alias,''),'Vecino/a'),p.sector,sum(l.kg_total) FROM profiles p JOIN recycling_logs l ON l.user_id=p.id WHERE p.ranking_opt_in AND l.created_at >= date_trunc('month',now() AT TIME ZONE 'America/Santiago') AT TIME ZONE 'America/Santiago' AND (_sector IS NULL OR p.sector=_sector) GROUP BY p.id,p.public_alias,p.sector ORDER BY sum(l.kg_total) DESC LIMIT 50 $$;
GRANT EXECUTE ON FUNCTION public.community_ranking(text) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.record_recycling(_client uuid,_point uuid,_items jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE lid uuid; total numeric:=0; carbon numeric:=0; reward integer; i jsonb; m materials%ROWTYPE; k numeric; n integer; sz text; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Inicia sesión'; END IF; PERFORM pg_advisory_xact_lock(hashtext(auth.uid()::text || _client::text)); SELECT id INTO lid FROM recycling_logs WHERE user_id=auth.uid() AND client_id=_client; IF lid IS NOT NULL THEN RETURN lid; END IF; IF jsonb_array_length(_items)<1 OR jsonb_array_length(_items)>50 THEN RAISE EXCEPTION 'Agrega materiales'; END IF; FOR i IN SELECT * FROM jsonb_array_elements(_items) LOOP SELECT * INTO m FROM materials WHERE id=i->>'id'; IF NOT FOUND THEN RAISE EXCEPTION 'Material inválido'; END IF; n:=(i->>'n')::integer; sz:=i->>'size'; IF n<1 OR n>10000 OR sz NOT IN ('pequeno','mediano','grande') THEN RAISE EXCEPTION 'Cantidad o tamaño inválido'; END IF; k:=n*CASE sz WHEN 'pequeno' THEN m.kg_pequeno WHEN 'grande' THEN m.kg_grande ELSE m.kg_mediano END; total:=total+k; carbon:=carbon+k*m.co2_por_kg; END LOOP; reward:=least(500,round(total*10)::integer+jsonb_array_length(_items)*2); INSERT INTO recycling_logs(user_id,point_id,kg_total,co2_total,puntos,client_id) VALUES(auth.uid(),_point,total,carbon,reward,_client) RETURNING id INTO lid; FOR i IN SELECT * FROM jsonb_array_elements(_items) LOOP SELECT * INTO m FROM materials WHERE id=i->>'id'; sz:=i->>'size'; k:=(i->>'n')::integer*CASE sz WHEN 'pequeno' THEN m.kg_pequeno WHEN 'grande' THEN m.kg_grande ELSE m.kg_mediano END; INSERT INTO recycling_log_items(log_id,material_id,tamano,cantidad,kg) VALUES(lid,m.id,sz,(i->>'n')::integer,k); END LOOP; RETURN lid; END $$;
REVOKE ALL ON FUNCTION public.record_recycling(uuid,uuid,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.record_recycling(uuid,uuid,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.review_suggestion(_id uuid,_approve boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s point_suggestions%ROWTYPE; BEGIN SELECT * INTO s FROM point_suggestions WHERE id=_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Propuesta no encontrada'; END IF; IF NOT (has_role(auth.uid(),'super_admin') OR EXISTS(SELECT 1 FROM collection_points WHERE id=s.point_id AND admin_id=auth.uid() AND is_admin(auth.uid()))) THEN RAISE EXCEPTION 'Sin permiso'; END IF; IF s.estado<>'pendiente' THEN RAISE EXCEPTION 'Ya revisada'; END IF; IF _approve THEN IF (s.lat IS NULL)<>(s.lng IS NULL) OR s.lat NOT BETWEEN -90 AND 90 OR s.lng NOT BETWEEN -180 AND 180 THEN RAISE EXCEPTION 'Coordenadas inválidas'; END IF; UPDATE collection_points SET horario=coalesce(s.horario,horario),lat=coalesce(s.lat,lat),lng=coalesce(s.lng,lng),verificado=CASE WHEN s.lat IS NOT NULL THEN true ELSE verificado END,fuente=CASE WHEN s.lat IS NOT NULL THEN 'GPS en terreno, revisado por administración' ELSE fuente END,updated_at=now() WHERE id=s.point_id; IF s.materiales IS NOT NULL THEN DELETE FROM point_materials WHERE point_id=s.point_id; INSERT INTO point_materials(point_id,material_id) SELECT s.point_id,unnest(s.materiales); END IF; END IF; UPDATE point_suggestions SET estado=CASE WHEN _approve THEN 'aprobada' ELSE 'rechazada' END WHERE id=_id; END $$;
REVOKE ALL ON FUNCTION public.review_suggestion(uuid,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.review_suggestion(uuid,boolean) TO authenticated;